export function roundCents(value) {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}
export function applyDiscount(amount, percent = 0) {
  if (percent < 0 || percent > 100) throw new Error("Invalid discount percent");
  return roundCents(amount * (1 - percent / 100));
}
export function calculateTax(subtotal, rate = 0) {
  if (rate < 0) throw new Error("Invalid tax rate");
  return roundCents(subtotal * rate);
}

