import { applyDiscount, calculateTax, roundCents } from "./tax.mjs";

export function calculateInvoice(items, { discountPercent = 0, taxRate = 0 } = {}) {
  let rawSubtotal = 0;
  for (const item of items) {
    if (item.qty < 0 || item.unitPrice < 0) throw new Error("Negative quantity or price");
    rawSubtotal += item.qty * item.unitPrice;
  }
  const subtotal = roundCents(rawSubtotal);
  const discounted = applyDiscount(subtotal, discountPercent);
  const tax = calculateTax(discounted, taxRate);
  return { subtotal, discounted, tax, total: roundCents(discounted + tax) };
}

